// Build scripts/opencode-roster-mcp.js (the MCP sidecar) and
// scripts/opencode-roster-plugin.js (the v2 plugin): one bun-runnable file each.
// Run: bun run build (in dev/opencode-roster)

import fs from "node:fs"
import path from "node:path"

const tasks = [
  { entry: path.join(import.meta.dir, "src", "mcp", "server.ts"), out: "opencode-roster-mcp.js" },
  { entry: path.join(import.meta.dir, ".opencode", "plugins", "opencode-roster.ts"), out: "opencode-roster-plugin.js" },
]
const banner =
  "// Built from dev/opencode-roster by dev/opencode-roster/build.ts. Do not edit this file; edit the source and build again.\n"
for (const task of tasks) {
  const result = await Bun.build({ entrypoints: [task.entry], target: "bun", format: "esm", minify: false })
  if (!result.success) {
    for (const message of result.logs) console.error(message)
    process.exit(1)
  }
  const code = (await result.outputs[0]!.text()).replace(/^#!.*\n/, "")
  const outfile = path.resolve(import.meta.dir, "..", "..", "scripts", task.out)
  fs.writeFileSync(outfile, banner + code)
  console.log(`Built ${outfile} (${fs.statSync(outfile).size} bytes)`)
}
